//! Operator-filter registry/helper analogue for Vegeta S3 NFT ecosystem traffic.
use cosmwasm_std::{entry_point,to_json_binary,Addr,Binary,Deps,DepsMut,Env,MessageInfo,Response,StdResult};use cw_storage_plus::{Map};use schemars::JsonSchema;use serde::{Deserialize,Serialize};
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]pub struct InstantiateMsg{}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]#[serde(rename_all="snake_case")]pub enum ExecuteMsg{RegisterAndSubscribe{registrant:String,subscription:String},SetOperatorAllowed{registrant:String,operator:String,allowed:bool}}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]#[serde(rename_all="snake_case")]pub enum QueryMsg{IsOperatorAllowed{registrant:String,operator:String}}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]pub struct BoolResponse{pub value:bool}
const SUBSCRIPTIONS:Map<&str,Addr>=Map::new("subscriptions");const BLOCKED:Map<(&str,&str),bool>=Map::new("blocked");
#[entry_point]pub fn instantiate(_deps:DepsMut,_:Env,_:MessageInfo,_:InstantiateMsg)->StdResult<Response>{Ok(Response::new())}
#[entry_point]pub fn execute(deps:DepsMut,_:Env,_info:MessageInfo,msg:ExecuteMsg)->StdResult<Response>{match msg{ExecuteMsg::RegisterAndSubscribe{registrant,subscription}=>{let r=deps.api.addr_validate(&registrant)?;let s=deps.api.addr_validate(&subscription)?;SUBSCRIPTIONS.save(deps.storage,r.as_str(),&s)?;Ok(Response::new())},ExecuteMsg::SetOperatorAllowed{registrant,operator,allowed}=>{let r=deps.api.addr_validate(&registrant)?;let o=deps.api.addr_validate(&operator)?;BLOCKED.save(deps.storage,(r.as_str(),o.as_str()),&!allowed)?;Ok(Response::new())}}}
#[entry_point]pub fn query(deps:Deps,_:Env,msg:QueryMsg)->StdResult<Binary>{match msg{QueryMsg::IsOperatorAllowed{registrant,operator}=>{let owner=SUBSCRIPTIONS.may_load(deps.storage,&registrant)?.map(|x|x.into_string()).unwrap_or(registrant);let blocked=BLOCKED.may_load(deps.storage,(&owner,&operator))?.unwrap_or(false);to_json_binary(&BoolResponse{value:!blocked})}}}
#[cfg(test)]mod tests{use super::*;use cosmwasm_std::testing::{mock_dependencies,mock_env,mock_info};#[test]fn subscription_redirects_operator_policy_key(){let mut d=mock_dependencies();instantiate(d.as_mut(),mock_env(),mock_info("x",&[]),InstantiateMsg{}).unwrap();execute(d.as_mut(),mock_env(),mock_info("x",&[]),ExecuteMsg::RegisterAndSubscribe{registrant:"collection".into(),subscription:"shared".into()}).unwrap();execute(d.as_mut(),mock_env(),mock_info("x",&[]),ExecuteMsg::SetOperatorAllowed{registrant:"shared".into(),operator:"operator".into(),allowed:false}).unwrap();let b=BLOCKED.load(d.as_ref().storage,("shared","operator")).unwrap();assert!(b);}}
